const mail = $json || {};

/**
 * Extracts a readable email address from common Gmail payload shapes.
 * @param {*} value Raw sender value.
 * @returns {string} Normalized email address.
 */
function extractEmail(value) {
  if (!value) return "";

  if (Array.isArray(value)) {
    for (const entry of value) {
      const found = extractEmail(entry);
      if (found) return found;
    }
    return "";
  }

  if (typeof value === "object") {
    if (value.address) return String(value.address).trim().toLowerCase();
    if (value.email) return String(value.email).trim().toLowerCase();
    if (value.value) return extractEmail(value.value);
    if (value.text) return extractEmail(value.text);
  }

  const text = String(value).trim();
  const angleMatch = text.match(/<([^<>\s]+@[^<>\s]+)>/);
  if (angleMatch) return angleMatch[1].trim().toLowerCase();

  const plainMatch = text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return plainMatch ? plainMatch[0].trim().toLowerCase() : "";
}

/**
 * Gets the Gmail sender display name without inventing one.
 * @param {*} value Raw sender value.
 * @returns {string} Sender display name or an empty string.
 */
function extractName(value) {
  if (!value) return "";
  if (Array.isArray(value)) return value.length ? extractName(value[0]) : "";
  if (typeof value === "object") {
    if (value.name) return String(value.name).trim();
    if (value.value) return extractName(value.value);
    if (value.text) return extractName(value.text);
  }

  const text = String(value).trim();
  const match = text.match(/^\s*([^<]+?)\s*</);
  return match ? match[1].replace(/^['\"]|['\"]$/g, "").trim() : "";
}

const rawFrom = mail.from ?? mail.From ?? mail.headers?.from ?? "";
const creatorEmail = extractEmail(rawFrom);
const creatorName = extractName(rawFrom);
const subject = String(mail.subject ?? mail.Subject ?? "").trim();
const textPlain = String(mail.text ?? mail.textPlain ?? mail.body ?? "").trim();
const html = String(mail.html ?? mail.textAsHtml ?? mail.textHtml ?? "").trim();
const body = textPlain || html;
const gmailMessageId = String(mail.id ?? "").trim();
const gmailThreadId = String(mail.threadId ?? "").trim();
const sourceMessageId = String(mail.messageId ?? gmailMessageId).trim();
const receivedAt = mail.date ? new Date(mail.date).toISOString() : new Date().toISOString();

const validationErrors = [];
if (!gmailMessageId) validationErrors.push("gmail-message-id-missing");
if (!creatorEmail) validationErrors.push("sender-email-missing");
if (!body) validationErrors.push("message-body-missing");

return [{
  json: {
    creatorEmail,
    creatorName,
    subject,
    body,
    sourceMessageId,
    gmailMessageId,
    gmailThreadId,
    receivedAt,
    source: "email",
    creatorType: "external",
    isProcessable: validationErrors.length === 0,
    validationErrors
  }
}];

const intake = $('Check Daily Limit').item.json;
let output = $json.output ?? $json;

if (typeof output === 'string') {
  try {
    output = JSON.parse(output);
  } catch {
    output = {};
  }
}

const allowedCategories = ['Technical Task', 'User Story', 'Bug Request'];
const allowedPriorities = ['urgent', 'medium', 'low'];
const title = String(output.title || '').trim();
const description = String(output.description || '').trim();
const category = String(output.category || '').trim();
const priority = String(output.priority || '').trim();
const dueDate = String(output.dueDate || '').trim();
const errors = [];

if (!title) errors.push('ai-title-missing');
if (!description) errors.push('ai-description-missing');
if (!allowedCategories.includes(category)) errors.push('ai-category-invalid');
if (!allowedPriorities.includes(priority)) errors.push('ai-priority-invalid');
if (dueDate && !/^\d{4}-\d{2}-\d{2}$/.test(dueDate)) errors.push('ai-due-date-invalid');

const sourceSubtasks = Array.isArray(output.subtasks) ? output.subtasks.slice(0, 6) : [];
const subtasks = {};
let index = 1;

for (const entry of sourceSubtasks) {
  const subtaskTitle = String(entry || '').trim();
  if (!subtaskTitle) continue;
  subtasks[`s${String(index).padStart(3, '0')}`] = { title: subtaskTitle, completed: false };
  index += 1;
}

const now = new Date().toISOString();
const aiOutputValid = errors.length === 0;
const note = 'Dieses Ticket wurde KI-generiert.';
const finalDescription = description ? `${description}\n\n${note}` : note;

return [{
  json: {
    ...intake,
    aiOutputValid,
    aiValidationErrors: errors,
    taskCandidate: {
      title,
      description: finalDescription,
      dueDate,
      priority,
      category,
      assignedTo: [],
      column: 'triage',
      order: Date.now(),
      creatorId: '',
      creatorName: intake.creatorName || '',
      creatorEmail: intake.creatorEmail,
      creatorType: 'external',
      aiGenerated: true,
      source: 'email',
      sourceMessageId: intake.sourceMessageId || '',
      createdAt: now,
      updatedAt: now,
      subtasks
    }
  }
}];

const original = $('Ready for Firebase').item.json;
const taskId = String($json.name || '').trim();

return [{
  json: {
    ...original,
    firebaseCreated: Boolean(taskId),
    taskId,
    firebaseResponse: $json,
    createdTask: taskId ? { id: taskId, ...original.taskCandidate } : null
  }
}];

const original = $('Ready for Firebase').item.json;
const rawError = $json.error?.message || $json.message || $json.description || '';
const processingError = String(rawError || 'Firebase did not create a Join task.').trim();

return [{
  json: {
    ...original,
    firebaseCreated: false,
    processingStatus: 'firebase-create-failed',
    shouldSendErrorEmail: true,
    processingError
  }
}];

const item = $input.first().json;
const task = item.createdTask || item.taskCandidate || {};
const greeting = item.creatorName ? `Hallo ${item.creatorName},` : 'Hallo,';
const deadline = task.dueDate ? task.dueDate : 'keine angegeben';

return [{
  json: {
    ...item,
    responseType: 'success',
    responseSubject: `Join: Ticket „${task.title || 'Neue Anfrage'}“ wurde erstellt`,
    responseText: `${greeting}\n\ndeine Anfrage wurde erfolgreich verarbeitet und als Ticket im Join-Board angelegt.\n\nTitel: ${task.title || '-'}\nKategorie: ${task.category || '-'}\nPriorität: ${task.priority || '-'}\nDeadline: ${deadline}\nStatus: Triage\nTicket-ID: ${item.taskId || '-'}\n\nDu wirst bei späteren Statusänderungen automatisch informiert.\n\nDies ist eine automatisch erzeugte Bestätigung.`,
    mailboxTarget: 'erledigt'
  }
}];

const item = $input.first().json;
const greeting = item.creatorName ? `Hallo ${item.creatorName},` : 'Hallo,';

return [{
  json: {
    ...item,
    responseType: 'limit',
    responseSubject: 'Join: Tageslimit für neue Anfragen erreicht',
    responseText: `${greeting}\n\ndeine E-Mail wurde empfangen, aber heute wurde das Tageslimit von ${item.dailyLimit?.limit || 10} automatisch verarbeiteten Anfragen bereits erreicht.\n\nEs wurde kein neues Join-Ticket erstellt und für diese Anfrage wurde keine KI-Verarbeitung gestartet. Bitte sende die Anfrage am nächsten Tag erneut oder wende dich direkt an das Team.\n\nDies ist eine automatisch erzeugte Nachricht.`,
    mailboxTarget: 'erledigt'
  }
}];

const item = $input.first().json;
const greeting = item.creatorName ? `Hallo ${item.creatorName},` : 'Hallo,';
const canReply = Boolean(String(item.creatorEmail || '').trim());

return [{
  json: {
    ...item,
    canReply,
    responseType: 'error',
    responseSubject: 'Join: Anfrage erhalten – manuelle Bearbeitung erforderlich',
    responseText: `${greeting}\n\ndeine Anfrage ist bei uns eingegangen, konnte jedoch nicht vollständig automatisch verarbeitet werden. Es wurde deshalb keine erfolgreiche automatische Ticket-Erstellung bestätigt.\n\nDas Team kann die Anfrage manuell prüfen und sich bei Bedarf zeitnah melden.\n\nDies ist eine automatisch erzeugte Nachricht.`,
    mailboxTarget: 'zu bearbeiten'
  }
}];

return $input.all().map((item) => ({
  json: {
    ...item.json,
    responseEmailSent: false,
    processingStatus: 'manual-review-no-sender',
    mailboxActionRequired: true,
    mailboxTarget: 'zu bearbeiten'
  }
}));

const incoming = $('Normalize Incoming Email').item.json;
const tasks = $input.first()?.json ?? {};
const limit = 10;

const viennaDateFormatter = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Vienna',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
});


/**
 * Returns a calendar date in the Europe/Vienna timezone.
 * @param {string|Date} value Date value.
 * @returns {string} Date formatted as YYYY-MM-DD.
 */
function getViennaDate(value) {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return '';
  }

  return viennaDateFormatter.format(date);
}


const today = getViennaDate(new Date());

const count = Object.values(tasks).filter((task) => {
  return task?.source === 'email'
    && task?.aiGenerated === true
    && getViennaDate(task?.createdAt) === today;
}).length;

const limitReached = count >= limit;

return [{
  json: {
    ...incoming,
    limitReached,
    dailyLimit: {
      date: today,
      limit,
      count,
      remaining: Math.max(0, limit - count)
    }
  }
}];
